import React, { useState, useEffect, useMemo } from 'react';
import { Message, KnowledgeItem, EmotionType } from '../types';
import { formatBotMessage } from '../utils/formatMessage';

interface ChatMessageProps {
  message: Message;
  knowledgeSources?: KnowledgeItem[];
  onSimilarQuestionClick?: (question: string) => void;
}

const emotionIcons: Record<EmotionType, string> = {
  happy: '😊',
  sad: '😢',
  anxious: '😰',
  angry: '😠',
  lonely: '🥺',
  neutral: '😌',
  hopeful: '🌟',
  confused: '😕',
  frustrated: '😤',
  guilty: '😔',
  shameful: '😳',
  proud: '😊'
};

const emotionLabels: Record<EmotionType, string> = {
  happy: '开心',
  sad: '低落',
  anxious: '焦虑',
  angry: '愤怒',
  lonely: '孤独',
  neutral: '平稳',
  hopeful: '充满希望',
  confused: '迷茫困惑',
  frustrated: '挫败',
  guilty: '内疚',
  shameful: '羞愧',
  proud: '自豪'
};

function typingInterval(contentLength: number): { step: number; ms: number } {
  if (contentLength > 800) return { step: 8, ms: 12 };
  if (contentLength > 400) return { step: 4, ms: 16 };
  if (contentLength > 150) return { step: 2, ms: 22 };
  return { step: 1, ms: 28 };
}

export const ChatMessage: React.FC<ChatMessageProps> = ({
  message,
  knowledgeSources,
  onSimilarQuestionClick
}) => {
  const [displayedContent, setDisplayedContent] = useState('');
  const [isTyping, setIsTyping] = useState(message.type === 'bot');
  const [refsExpanded, setRefsExpanded] = useState(false);

  const hasRefs =
    (knowledgeSources && knowledgeSources.length > 0) ||
    (message.similarQuestions && message.similarQuestions.length > 0);

  useEffect(() => {
    if (message.type !== 'bot') {
      setDisplayedContent(message.content);
      setIsTyping(false);
      return;
    }

    setDisplayedContent('');
    setIsTyping(true);
    setRefsExpanded(false);

    const content = message.content;
    const { step, ms } = typingInterval(content.length);
    let index = 0;

    const interval = window.setInterval(() => {
      index = Math.min(index + step, content.length);
      setDisplayedContent(content.slice(0, index));
      if (index >= content.length) {
        window.clearInterval(interval);
        setIsTyping(false);
      }
    }, ms);

    return () => window.clearInterval(interval);
  }, [message.content, message.type]);

  const formattedBody = useMemo(
    () => (message.type === 'bot' && !isTyping ? formatBotMessage(displayedContent) : null),
    [message.type, isTyping, displayedContent]
  );

  const skipTyping = () => {
    if (isTyping && message.type === 'bot') {
      setDisplayedContent(message.content);
      setIsTyping(false);
    }
  };

  return (
    <div className={`message-wrapper ${message.type}`}>
      <div className="message-avatar">
        {message.type === 'user' ? (
          <div className="avatar user-avatar" aria-hidden="true">
            👤
          </div>
        ) : (
          <div
            className="avatar bot-avatar"
            style={{ backgroundColor: message.emotionStyle?.color || '#607D8B' }}
            aria-hidden="true"
          >
            🧠
          </div>
        )}
      </div>

      <div className="message-content-wrapper">
        {message.type === 'bot' && message.emotion && (
          <div className="emotion-tag" style={{ color: message.emotionStyle?.color }}>
            {emotionIcons[message.emotion.emotion]} {emotionLabels[message.emotion.emotion]}
          </div>
        )}

        <div className={`message-bubble ${message.type}`}>
          <div className="message-text">
            {formattedBody ?? (
              <>
                {displayedContent}
                {isTyping && <span className="typing-cursor" aria-hidden="true">|</span>}
              </>
            )}
          </div>

          {isTyping && message.type === 'bot' && (
            <button type="button" className="skip-typing-btn" onClick={skipTyping}>
              跳过动画
            </button>
          )}

          {message.timestamp && !isTyping && (
            <div className="message-timestamp">{message.timestamp}</div>
          )}

          {!isTyping && message.risk && (message.risk.level === 'high' || message.risk.level === 'critical') && (
            <div className={`risk-warning ${message.risk.level}`}>
              <div className="warning-icon" aria-hidden="true">
                ⚠️
              </div>
              <div className="warning-content">
                <div className="warning-title">危机预警</div>
                <div className="warning-message">{message.risk.warningMessage}</div>
                <div className="warning-hotline">{message.risk.hotline}</div>
              </div>
            </div>
          )}

          {!isTyping && hasRefs && (
            <div className="message-refs">
              <button
                type="button"
                className="refs-toggle"
                onClick={() => setRefsExpanded((v) => !v)}
                aria-expanded={refsExpanded}
              >
                {refsExpanded ? '收起参考' : '展开参考'}
                <span className="refs-count">
                  {(knowledgeSources?.length ?? 0) + (message.similarQuestions?.length ?? 0)} 条
                </span>
              </button>

              {refsExpanded && (
                <div className="refs-body">
                  {knowledgeSources && knowledgeSources.length > 0 && (
                    <div className="knowledge-sources">
                      <h4>📚 参考知识</h4>
                      {knowledgeSources.map((item, idx) => (
                        <div key={idx} className="knowledge-item">
                          <div className="knowledge-question">{item.question}</div>
                          <div className="knowledge-answer">{item.answer}</div>
                        </div>
                      ))}
                    </div>
                  )}

                  {message.similarQuestions && message.similarQuestions.length > 0 && (
                    <div className="similar-questions">
                      <h4>💡 相似问题</h4>
                      {message.similarQuestions.map((item, idx) => (
                        <div
                          key={idx}
                          className="similar-question-item"
                          role="button"
                          tabIndex={0}
                          onClick={() => onSimilarQuestionClick?.(item.question)}
                          onKeyDown={(e) => e.key === 'Enter' && onSimilarQuestionClick?.(item.question)}
                        >
                          <div className="question-text">{item.question}</div>
                          {item.keywords && <div className="keywords">{item.keywords}</div>}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};
